        };

        if let Some(spaces_count) = spaces_count_opt {
            let (style, icon) = match icon_override {
                Some(icon_override) => (
                    if let Some(style_override) = icon_override.style {
                        style_override
                    } else {
                        iconify_style(self.style())
                    },
                    icon_override
                        .glyph
                        .unwrap_or_else(|| icon_for_file(self.file))
                        .to_string(),
                ),
